import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';
import { spawnSync } from 'node:child_process';
import { pathToFileURL } from 'node:url';
import { packContext } from '../context-packet.js';

const section = (id, text, priority = 0, required = false) => ({ id, text, priority, required });
const frame = (value) => `### ${JSON.stringify(value.id)}\n${value.text}\n`;
const modulePath = resolve('context-packet.js');

function invoke(args) {
  return spawnSync(process.execPath, [modulePath, ...args], { encoding: 'utf8' });
}

test('validates top-level values and every required field without coercion', () => {
  for (const budget of [-1, 1.5, Number.MAX_SAFE_INTEGER + 1, NaN, Infinity, '1', null]) {
    assert.throws(() => packContext([], budget), Error);
  }
  for (const value of [null, {}, 'sections', 1, true]) {
    assert.throws(() => packContext(value, 0), Error);
  }

  const invalidSections = [
    null,
    [],
    { id: '', text: '', priority: 0, required: false },
    { id: 1, text: '', priority: 0, required: false },
    { id: 'id', text: 1, priority: 0, required: false },
    { id: 'id', text: '', priority: -1, required: false },
    { id: 'id', text: '', priority: 1.1, required: false },
    { id: 'id', text: '', priority: Number.MAX_SAFE_INTEGER + 1, required: false },
    { id: 'id', text: '', priority: 0, required: 0 },
    { id: 'id', text: '', priority: 0 },
  ];
  for (const value of invalidSections) {
    assert.throws(() => packContext([value], 0), Error);
  }

  const trailingInvalid = section('bad', '', 0, false);
  trailingInvalid.text = null;
  assert.throws(() => packContext([section('valid', '', 0, false), trailingInvalid], 0), Error);

  const sparse = [section('a', '')];
  sparse.length = 3;
  sparse[2] = section('c', '');
  assert.throws(() => packContext(sparse, 1000), Error);
});

test('accepts exact unusual IDs and frames text without normalization', () => {
  const values = [
    section('__proto__', 'first\r\nline', 0, true),
    section(' 雪\n"\\\0', 'é\n\0', 0, true),
  ];
  const expected = values.map(frame).join('');
  const result = packContext(values, Buffer.byteLength(expected));
  assert.deepEqual(result, {
    text: expected,
    bytes: Buffer.byteLength(expected, 'utf8'),
    included: values.map(({ id }) => id),
    omitted: [],
  });
  assert.throws(() => packContext([section('A', ''), section('A', '')], 100), Error);
  assert.doesNotThrow(() => packContext([section('A', ''), section('a', '')], 100));
});

test('orders required by input and optionals by priority with stable ties', () => {
  const input = [
    section('low', 'L', 1),
    section('required-1', 'R1', 0, true),
    section('tie-1', 'T1', 9),
    section('required-2', 'R2', 999, true),
    section('tie-2', 'T2', 9),
  ];
  const snapshot = structuredClone(input);
  const result = packContext(input, 1000);
  assert.deepEqual(result.included, ['required-1', 'required-2', 'tie-1', 'tie-2', 'low']);
  assert.equal(result.text, result.included.map((id) => frame(input.find((item) => item.id === id))).join(''));
  assert.deepEqual(input, snapshot);
});

test('uses UTF-8 framed byte costs, exact fits, skip-continue, and input-order omissions', () => {
  const expensive = section('first', 'x'.repeat(40), 100);
  const fitting = section('雪', 'é', 5);
  const laterExpensive = section('last', 'y'.repeat(40), 50);
  const exact = Buffer.byteLength(frame(fitting), 'utf8');
  const result = packContext([expensive, fitting, laterExpensive], exact);
  assert.deepEqual(result, {
    text: frame(fitting),
    bytes: exact,
    included: ['雪'],
    omitted: ['first', 'last'],
  });
});

test('required overflow validates all input first and never returns a partial set', () => {
  const invalid = section('invalid', '', 0, false);
  invalid.required = 'false';
  assert.throws(
    () => packContext([section('needed', 'large', 0, true), invalid], 0),
    /required must be a boolean/,
  );
  assert.throws(() => packContext([section('one', '1', 0, true), section('two', '2', 0, true)], 1), Error);
});

test('CLI succeeds with exactly one JSON result and is safe to import', async () => {
  const directory = mkdtempSync(join(tmpdir(), 'context-packet-'));
  try {
    const inputPath = join(directory, 'input.json');
    const value = section('雪', 'é', 2, false);
    writeFileSync(inputPath, JSON.stringify({ sections: [value], maxBytes: 100, ignored: true }), 'utf8');
    const child = invoke([inputPath]);
    assert.equal(child.status, 0);
    assert.equal(child.signal, null);
    assert.equal(child.stderr, '');
    assert.equal(child.stdout, `${JSON.stringify(packContext([value], 100))}\n`);

    const imported = spawnSync(
      process.execPath,
      ['--input-type=module', '--eval', `await import(${JSON.stringify(pathToFileURL(modulePath).href)})`],
      { encoding: 'utf8' },
    );
    assert.equal(imported.status, 0);
    assert.equal(imported.stdout, '');
    assert.equal(imported.stderr, '');
  } finally {
    rmSync(directory, { recursive: true, force: true });
  }
});

test('CLI reports argument, file, JSON, API, and required-budget errors', () => {
  const directory = mkdtempSync(join(tmpdir(), 'context-packet-'));
  try {
    const cases = [
      [],
      ['one.json', 'two.json'],
      [join(directory, 'missing.json')],
    ];
    const malformed = join(directory, 'malformed.json');
    writeFileSync(malformed, '{', 'utf8');
    cases.push([malformed]);
    const invalidApi = join(directory, 'invalid-api.json');
    writeFileSync(invalidApi, JSON.stringify({ sections: [], maxBytes: -1 }), 'utf8');
    cases.push([invalidApi]);
    const overflow = join(directory, 'overflow.json');
    writeFileSync(overflow, JSON.stringify({ sections: [section('required', 'x', 0, true)], maxBytes: 0 }), 'utf8');
    cases.push([overflow]);

    for (const args of cases) {
      const child = invoke(args);
      assert.equal(child.status, 2, `args: ${JSON.stringify(args)}`);
      assert.equal(child.stdout, '');
      assert.notEqual(child.stderr, '');
    }
  } finally {
    rmSync(directory, { recursive: true, force: true });
  }
});

